', '2026-01-01T00:00:00+00:00', 'Caesar Cipher', 'Strings', 'medium') ON CONFLICT(id) DO UPDATE SET title = excluded.title, category = excluded.category, difficulty = excluded.difficulty;
INSERT INTO problems (id, owner_teacher_id, visibility, statement, func_name, param_names, rubric, reference_solution, test_cases, starter_code, created_at, title, category, difficulty) VALUES ('bank:P12_valid_parentheses', NULL, 'system', 'Write a function valid_parentheses(s) that returns True if every opening bracket in s (''('', ''['', ''{'') has a matching closing bracket in the correct order, False otherwise. s may also contain other characters, which should be ignored.', 'valid_parentheses', '["s"]', '{"correctness": 60, "efficiency": 10, "code_style": 15, "edge_case_handling": 15}', 'def valid_parentheses(s):
    pairs = {'')'': ''('', '']'': ''['', ''}'': ''{''}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
